ALTER TABLE schema_migrations
    ADD COLUMN IF NOT EXISTS filename TEXT,
    ADD COLUMN IF NOT EXISTS checksum TEXT;

CREATE TABLE IF NOT EXISTS maintenance_epochs (
    id UUID PRIMARY KEY,
    campaign TEXT NOT NULL
        CHECK (
            campaign IN (
                'account-identity-cutover',
                'schema-apply',
                'purge',
                'reconcile',
                'flatten'
            )
        ),
    opened_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    opened_by TEXT NOT NULL,
    scope_note TEXT NOT NULL,
    released_at TIMESTAMPTZ,
    released_by_command TEXT,
    CHECK (
        (released_at IS NULL AND released_by_command IS NULL)
        OR
        (released_at IS NOT NULL AND released_by_command IS NOT NULL)
    )
);

CREATE UNIQUE INDEX IF NOT EXISTS maintenance_epochs_one_open
    ON maintenance_epochs ((TRUE))
    WHERE released_at IS NULL;

CREATE INDEX IF NOT EXISTS maintenance_epochs_open_lookup
    ON maintenance_epochs (opened_at, id)
    WHERE released_at IS NULL;

CREATE TABLE IF NOT EXISTS destructive_batches (
    id UUID PRIMARY KEY,
    maintenance_epoch_id UUID NOT NULL
        REFERENCES maintenance_epochs(id)
        DEFERRABLE INITIALLY DEFERRED,
    campaign TEXT NOT NULL
        CHECK (
            campaign IN (
                'account-identity-cutover',
                'schema-apply',
                'purge',
                'reconcile',
                'flatten'
            )
        ),
    status TEXT NOT NULL DEFAULT 'pending'
        CHECK (status IN ('pending', 'applied', 'verified', 'aborted')),
    backup_manifest_path TEXT,
    backup_manifest_sha256 TEXT
        CHECK (
            backup_manifest_sha256 IS NULL
            OR backup_manifest_sha256 ~ '^[0-9a-f]{64}$'
        ),
    intent JSONB NOT NULL DEFAULT '{}'::JSONB
        CHECK (jsonb_typeof(intent) = 'object'),
    migration_plan JSONB NOT NULL DEFAULT '[]'::JSONB
        CHECK (jsonb_typeof(migration_plan) = 'array'),
    target_receipts JSONB NOT NULL DEFAULT '{}'::JSONB
        CHECK (jsonb_typeof(target_receipts) = 'object'),
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    verified_at TIMESTAMPTZ,
    aborted_at TIMESTAMPTZ,
    abort_disposition TEXT,
    UNIQUE (maintenance_epoch_id),
    CHECK (
        (status = 'verified' AND verified_at IS NOT NULL)
        OR
        (status <> 'verified' AND verified_at IS NULL)
    ),
    CHECK (
        (
            status = 'aborted'
            AND aborted_at IS NOT NULL
            AND abort_disposition IS NOT NULL
        )
        OR
        (
            status <> 'aborted'
            AND aborted_at IS NULL
            AND abort_disposition IS NULL
        )
    )
);

CREATE INDEX IF NOT EXISTS destructive_batches_epoch_lookup
    ON destructive_batches (maintenance_epoch_id, created_at);

DO $migration$
DECLARE
    target_schema TEXT := current_schema();
    trigger_name TEXT :=
        'gobby_maintenance_epoch_login_' || SUBSTRING(MD5(current_schema()) FOR 16);
BEGIN
    IF target_schema <> 'public' THEN
        RETURN;
    END IF;

    EXECUTE FORMAT(
        $function$
        CREATE OR REPLACE FUNCTION %I.gobby_maintenance_epoch_login_guard()
        RETURNS event_trigger
        LANGUAGE plpgsql
        SECURITY DEFINER
        AS $body$
        DECLARE
            active_epoch UUID;
            supplied_epoch TEXT;
        BEGIN
            IF pg_catalog.current_schema() IS DISTINCT FROM %L THEN
                RETURN;
            END IF;
            IF pg_catalog.pg_is_in_recovery() THEN
                RETURN;
            END IF;

            BEGIN
                SELECT id
                INTO active_epoch
                FROM %I.maintenance_epochs
                WHERE released_at IS NULL;
            EXCEPTION
                WHEN undefined_table OR invalid_schema_name THEN
                    RETURN;
            END;

            IF active_epoch IS NULL THEN
                RETURN;
            END IF;

            supplied_epoch :=
                pg_catalog.current_setting('gobby.maintenance_epoch', TRUE);
            IF supplied_epoch IS DISTINCT FROM active_epoch::TEXT THEN
                RAISE EXCEPTION USING
                    ERRCODE = '55000',
                    MESSAGE = pg_catalog.format(
                        'GOBBY_MAINTENANCE_EPOCH %%s is active; reconnect through '
                        '`gobby hub-maintenance resume` with the epoch token '
                        '(repair escape: superuser options=''-c event_triggers=off'')',
                        active_epoch
                    );
            END IF;
        END;
        $body$
        $function$,
        target_schema,
        target_schema,
        target_schema
    );

    IF NOT EXISTS (
        SELECT 1
        FROM pg_catalog.pg_event_trigger
        WHERE evtname = trigger_name
    ) THEN
        EXECUTE FORMAT(
            'CREATE EVENT TRIGGER %I ON login '
            'EXECUTE FUNCTION %I.gobby_maintenance_epoch_login_guard()',
            trigger_name,
            target_schema
        );
    END IF;

    EXECUTE FORMAT('ALTER EVENT TRIGGER %I ENABLE ALWAYS', trigger_name);
END;
$migration$;

DO $migration$
DECLARE
    target_schema TEXT := current_schema();
BEGIN
    EXECUTE FORMAT(
        $function$
        CREATE OR REPLACE FUNCTION %I.gobby_maintenance_epoch_login_guard()
        RETURNS event_trigger
        LANGUAGE plpgsql
        SECURITY DEFINER
        SET search_path = pg_catalog
        AS $body$
        DECLARE
            active_epoch UUID;
            supplied_epoch TEXT;
        BEGIN
            IF pg_catalog.pg_is_in_recovery() THEN
                RETURN;
            END IF;

            BEGIN
                SELECT id
                INTO active_epoch
                FROM %I.maintenance_epochs
                WHERE released_at IS NULL;
            EXCEPTION
                WHEN undefined_table OR invalid_schema_name THEN
                    RETURN;
            END;

            IF active_epoch IS NULL THEN
                RETURN;
            END IF;

            supplied_epoch :=
                pg_catalog.current_setting('gobby.maintenance_epoch', TRUE);
            IF supplied_epoch IS DISTINCT FROM active_epoch::TEXT THEN
                RAISE EXCEPTION USING
                    ERRCODE = '55000',
                    MESSAGE =
                        'Gobby hub maintenance is active; use '
                        '`gobby hub-maintenance status` to inspect it or '
                        '`gobby hub-maintenance resume` from the operator shell.';
            END IF;
        END;
        $body$
        $function$,
        target_schema,
        target_schema
    );
END;
$migration$;

-- gobby:destructive
-- Scoped PostgreSQL authorization substrate for managed gcode executions.
-- Policy drops and PUBLIC privilege revocations run under the gated
-- destructive path on existing hubs; fresh installs apply directly.
-- Migration slots 367 and 368 are reserved by tasks #19404 and #19421.

SELECT pg_advisory_xact_lock(hashtextextended('gobby:agent-authorization:v1', 0));

DO $roles$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'gobby_agent_issuer') THEN
        CREATE ROLE gobby_agent_issuer;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'gobby_gcode_capability') THEN
        CREATE ROLE gobby_gcode_capability;
    END IF;
    IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'gobby_daemon_runtime') THEN
        CREATE ROLE gobby_daemon_runtime;
    END IF;

    ALTER ROLE gobby_agent_issuer
        NOLOGIN NOSUPERUSER INHERIT CREATEROLE NOCREATEDB
        NOREPLICATION NOBYPASSRLS;
    ALTER ROLE gobby_gcode_capability
        NOLOGIN NOSUPERUSER INHERIT NOCREATEROLE NOCREATEDB
        NOREPLICATION NOBYPASSRLS;
    ALTER ROLE gobby_daemon_runtime
        NOLOGIN NOSUPERUSER INHERIT NOCREATEROLE NOCREATEDB
        NOREPLICATION NOBYPASSRLS;
END
$roles$;

GRANT pg_signal_backend TO gobby_agent_issuer
    WITH ADMIN FALSE, INHERIT TRUE, SET FALSE;
GRANT gobby_gcode_capability TO gobby_agent_issuer
    WITH ADMIN TRUE, INHERIT FALSE, SET FALSE;

DO $runtime_membership$
BEGIN
    EXECUTE format(
        'GRANT %I TO %I WITH ADMIN FALSE, INHERIT FALSE, SET TRUE',
        'gobby_daemon_runtime',
        current_user
    );
END
$runtime_membership$;

CREATE SCHEMA IF NOT EXISTS gobby_agent_auth;

CREATE TABLE IF NOT EXISTS gobby_agent_auth.principal_bindings (
    id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    role_name NAME NOT NULL UNIQUE,
    owner_kind TEXT NOT NULL CHECK (owner_kind IN ('agent_run', 'tool_chat')),
    managed_execution_id UUID NOT NULL,
    agent_run_id UUID,
    session_id UUID NOT NULL,
    project_id UUID NOT NULL,
    issuing_machine_id UUID NOT NULL,
    issued_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    expires_at TIMESTAMPTZ NOT NULL,
    revoked_at TIMESTAMPTZ,
    credential_generation INTEGER NOT NULL CHECK (credential_generation > 0),
    CONSTRAINT principal_bindings_execution_generation
        UNIQUE (managed_execution_id, credential_generation),
    CONSTRAINT principal_bindings_expiry_after_issue CHECK (expires_at > issued_at),
    CONSTRAINT principal_bindings_revoke_after_issue
        CHECK (revoked_at IS NULL OR revoked_at >= issued_at)
);

CREATE INDEX IF NOT EXISTS idx_principal_bindings_active_role
ON gobby_agent_auth.principal_bindings(role_name)
WHERE revoked_at IS NULL;

CREATE INDEX IF NOT EXISTS idx_principal_bindings_execution
ON gobby_agent_auth.principal_bindings(managed_execution_id, credential_generation DESC);

CREATE INDEX IF NOT EXISTS idx_principal_bindings_expiry
ON gobby_agent_auth.principal_bindings(expires_at)
WHERE revoked_at IS NULL;

CREATE TABLE IF NOT EXISTS gobby_agent_auth.principal_audit_events (
    id BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    binding_id UUID REFERENCES gobby_agent_auth.principal_bindings(id) ON DELETE SET NULL,
    event_type TEXT NOT NULL CHECK (event_type IN ('issue', 'rotate', 'revoke', 'reconcile')),
    managed_execution_id UUID NOT NULL,
    role_name NAME NOT NULL,
    credential_generation INTEGER NOT NULL,
    project_id UUID NOT NULL,
    occurred_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    details JSONB NOT NULL DEFAULT '{}'::JSONB
);

ALTER SCHEMA gobby_agent_auth OWNER TO gobby_agent_issuer;
ALTER TABLE gobby_agent_auth.principal_bindings OWNER TO gobby_agent_issuer;
ALTER TABLE gobby_agent_auth.principal_audit_events OWNER TO gobby_agent_issuer;
ALTER SEQUENCE gobby_agent_auth.principal_audit_events_id_seq OWNER TO gobby_agent_issuer;

REVOKE ALL ON SCHEMA gobby_agent_auth FROM PUBLIC;
REVOKE ALL ON ALL TABLES IN SCHEMA gobby_agent_auth FROM PUBLIC;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA gobby_agent_auth FROM PUBLIC;
GRANT USAGE ON SCHEMA gobby_agent_auth TO gobby_gcode_capability, gobby_daemon_runtime;

CREATE OR REPLACE FUNCTION gobby_agent_auth.current_project_id()
RETURNS UUID
LANGUAGE plpgsql
STABLE
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
AS $function$
DECLARE
    binding_count INTEGER;
    bound_project_id UUID;
BEGIN
    SELECT count(*), min(project_id::TEXT)::UUID
    INTO binding_count, bound_project_id
    FROM principal_bindings
    WHERE role_name = session_user::NAME
      AND revoked_at IS NULL
      AND expires_at > clock_timestamp();

    IF binding_count <> 1 THEN
        RAISE EXCEPTION 'managed principal binding is missing, expired, revoked, or duplicated'
            USING ERRCODE = '42501';
    END IF;
    RETURN bound_project_id;
END
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.issue_principal(
    requested_execution_id UUID,
    requested_owner_kind TEXT,
    requested_session_id UUID,
    requested_agent_run_id UUID,
    requested_machine_id UUID,
    requested_expires_at TIMESTAMPTZ,
    requested_password TEXT
)
RETURNS TABLE(role_name NAME, credential_generation INTEGER)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    resolved_project_id UUID;
    resolved_agent_run_id UUID;
    derived_role_name NAME;
    binding_id UUID;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(requested_execution_id::TEXT, 0));
    IF requested_owner_kind NOT IN ('agent_run', 'tool_chat') THEN
        RAISE EXCEPTION 'unsupported managed principal owner kind'
            USING ERRCODE = '22023';
    END IF;
    IF requested_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'managed principal expiry must be in the future'
            USING ERRCODE = '22023';
    END IF;
    IF requested_password IS NULL OR requested_password = '' THEN
        RAISE EXCEPTION 'managed principal password must not be empty'
            USING ERRCODE = '22023';
    END IF;
    IF EXISTS (
        SELECT 1 FROM principal_bindings
        WHERE managed_execution_id = requested_execution_id
    ) THEN
        RAISE EXCEPTION 'managed execution already has a principal binding'
            USING ERRCODE = '23505';
    END IF;

    SELECT project_id, agent_run_id
    INTO resolved_project_id, resolved_agent_run_id
    FROM public.sessions
    WHERE id = requested_session_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'managed principal session does not exist'
            USING ERRCODE = '23503';
    END IF;
    IF resolved_agent_run_id IS DISTINCT FROM requested_agent_run_id THEN
        RAISE EXCEPTION 'managed principal agent run does not match its session'
            USING ERRCODE = '23503';
    END IF;
    IF requested_agent_run_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.agent_runs WHERE id = requested_agent_run_id
    ) THEN
        RAISE EXCEPTION 'managed principal agent run does not exist'
            USING ERRCODE = '23503';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.machines WHERE id = requested_machine_id) THEN
        RAISE EXCEPTION 'managed principal issuing machine does not exist'
            USING ERRCODE = '23503';
    END IF;

    derived_role_name := (
        'gobby_agent_' || replace(requested_execution_id::TEXT, '-', '') || '_1'
    )::NAME;
    EXECUTE format(
        'CREATE ROLE %I LOGIN PASSWORD %L VALID UNTIL %L INHERIT '
        'NOSUPERUSER NOCREATEROLE NOCREATEDB NOREPLICATION NOBYPASSRLS',
        derived_role_name,
        requested_password,
        requested_expires_at
    );
    EXECUTE format(
        'GRANT %I TO %I WITH ADMIN FALSE, INHERIT TRUE, SET FALSE',
        'gobby_gcode_capability',
        derived_role_name
    );

    INSERT INTO principal_bindings (
        role_name,
        owner_kind,
        managed_execution_id,
        agent_run_id,
        session_id,
        project_id,
        issuing_machine_id,
        expires_at,
        credential_generation
    ) VALUES (
        derived_role_name,
        requested_owner_kind,
        requested_execution_id,
        requested_agent_run_id,
        requested_session_id,
        resolved_project_id,
        requested_machine_id,
        requested_expires_at,
        1
    ) RETURNING id INTO binding_id;

    INSERT INTO principal_audit_events (
        binding_id,
        event_type,
        managed_execution_id,
        role_name,
        credential_generation,
        project_id
    ) VALUES (
        binding_id,
        'issue',
        requested_execution_id,
        derived_role_name,
        1,
        resolved_project_id
    );
    RETURN QUERY SELECT derived_role_name, 1;
END
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.rotate_principal(
    requested_execution_id UUID,
    requested_expires_at TIMESTAMPTZ,
    requested_password TEXT
)
RETURNS TABLE(role_name NAME, credential_generation INTEGER)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    source_binding principal_bindings%ROWTYPE;
    active_count INTEGER;
    next_generation INTEGER;
    derived_role_name NAME;
    binding_id UUID;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(requested_execution_id::TEXT, 0));
    IF requested_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'managed principal expiry must be in the future'
            USING ERRCODE = '22023';
    END IF;
    IF requested_password IS NULL OR requested_password = '' THEN
        RAISE EXCEPTION 'managed principal password must not be empty'
            USING ERRCODE = '22023';
    END IF;
    SELECT count(*) INTO active_count
    FROM principal_bindings
    WHERE managed_execution_id = requested_execution_id
      AND revoked_at IS NULL
      AND expires_at > clock_timestamp();
    IF active_count <> 1 THEN
        RAISE EXCEPTION 'rotation requires exactly one active principal binding'
            USING ERRCODE = '42501';
    END IF;
    SELECT * INTO STRICT source_binding
    FROM principal_bindings
    WHERE managed_execution_id = requested_execution_id
      AND revoked_at IS NULL
      AND expires_at > clock_timestamp();
    SELECT COALESCE(max(pb.credential_generation), 0) + 1
    INTO next_generation
    FROM principal_bindings pb
    WHERE pb.managed_execution_id = requested_execution_id;

    derived_role_name := (
        'gobby_agent_' || replace(requested_execution_id::TEXT, '-', '') || '_' || next_generation
    )::NAME;
    EXECUTE format(
        'CREATE ROLE %I LOGIN PASSWORD %L VALID UNTIL %L INHERIT '
        'NOSUPERUSER NOCREATEROLE NOCREATEDB NOREPLICATION NOBYPASSRLS',
        derived_role_name,
        requested_password,
        requested_expires_at
    );
    EXECUTE format(
        'GRANT %I TO %I WITH ADMIN FALSE, INHERIT TRUE, SET FALSE',
        'gobby_gcode_capability',
        derived_role_name
    );

    INSERT INTO principal_bindings (
        role_name,
        owner_kind,
        managed_execution_id,
        agent_run_id,
        session_id,
        project_id,
        issuing_machine_id,
        expires_at,
        credential_generation
    ) VALUES (
        derived_role_name,
        source_binding.owner_kind,
        requested_execution_id,
        source_binding.agent_run_id,
        source_binding.session_id,
        source_binding.project_id,
        source_binding.issuing_machine_id,
        requested_expires_at,
        next_generation
    ) RETURNING id INTO binding_id;

    INSERT INTO principal_audit_events (
        binding_id,
        event_type,
        managed_execution_id,
        role_name,
        credential_generation,
        project_id
    ) VALUES (
        binding_id,
        'rotate',
        requested_execution_id,
        derived_role_name,
        next_generation,
        source_binding.project_id
    );
    RETURN QUERY SELECT derived_role_name, next_generation;
END
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.revoke_principal(
    requested_execution_id UUID,
    requested_generation INTEGER DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    binding principal_bindings%ROWTYPE;
    revoked_count INTEGER := 0;
    remaining_sessions INTEGER;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(requested_execution_id::TEXT, 0));
    FOR binding IN
        SELECT * FROM principal_bindings
        WHERE managed_execution_id = requested_execution_id
          AND revoked_at IS NULL
          AND (
              requested_generation IS NULL
              OR credential_generation = requested_generation
          )
        ORDER BY credential_generation
        FOR UPDATE
    LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = binding.role_name) THEN
            EXECUTE format('ALTER ROLE %I NOLOGIN', binding.role_name);
            EXECUTE format(
                'REVOKE %I FROM %I',
                'gobby_gcode_capability',
                binding.role_name
            );
            PERFORM pg_terminate_backend(pid, 5000)
            FROM pg_stat_activity
            WHERE usename = binding.role_name::TEXT
              AND pid <> pg_backend_pid();
            SELECT count(*) INTO remaining_sessions
            FROM pg_stat_activity
            WHERE usename = binding.role_name::TEXT;
            IF remaining_sessions <> 0 THEN
                RAISE EXCEPTION 'managed principal still has active database sessions'
                    USING ERRCODE = '55006';
            END IF;
            EXECUTE format('DROP ROLE %I', binding.role_name);
        END IF;
        UPDATE principal_bindings
        SET revoked_at = clock_timestamp()
        WHERE id = binding.id;
        INSERT INTO principal_audit_events (
            binding_id,
            event_type,
            managed_execution_id,
            role_name,
            credential_generation,
            project_id
        ) VALUES (
            binding.id,
            'revoke',
            binding.managed_execution_id,
            binding.role_name,
            binding.credential_generation,
            binding.project_id
        );
        revoked_count := revoked_count + 1;
    END LOOP;
    RETURN revoked_count;
END
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.reconcile_principal(
    requested_execution_id UUID
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    binding principal_bindings%ROWTYPE;
    reconciled_count INTEGER := 0;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(requested_execution_id::TEXT, 0));
    FOR binding IN
        SELECT * FROM principal_bindings
        WHERE managed_execution_id = requested_execution_id
          AND revoked_at IS NULL
          AND (
              expires_at <= clock_timestamp()
              OR NOT EXISTS (
                  SELECT 1 FROM pg_roles WHERE rolname = principal_bindings.role_name
              )
          )
        ORDER BY credential_generation
    LOOP
        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = binding.role_name) THEN
            reconciled_count := reconciled_count + revoke_principal(
                requested_execution_id,
                binding.credential_generation
            );
        ELSE
            UPDATE principal_bindings
            SET revoked_at = clock_timestamp()
            WHERE id = binding.id;
            INSERT INTO principal_audit_events (
                binding_id,
                event_type,
                managed_execution_id,
                role_name,
                credential_generation,
                project_id,
                details
            ) VALUES (
                binding.id,
                'reconcile',
                binding.managed_execution_id,
                binding.role_name,
                binding.credential_generation,
                binding.project_id,
                '{"reason":"missing_role"}'::JSONB
            );
            reconciled_count := reconciled_count + 1;
        END IF;
    END LOOP;
    RETURN reconciled_count;
END
$function$;

ALTER FUNCTION gobby_agent_auth.current_project_id() OWNER TO gobby_agent_issuer;
ALTER FUNCTION gobby_agent_auth.issue_principal(UUID, TEXT, UUID, UUID, UUID, TIMESTAMPTZ, TEXT)
    OWNER TO gobby_agent_issuer;
ALTER FUNCTION gobby_agent_auth.rotate_principal(UUID, TIMESTAMPTZ, TEXT)
    OWNER TO gobby_agent_issuer;
ALTER FUNCTION gobby_agent_auth.revoke_principal(UUID, INTEGER)
    OWNER TO gobby_agent_issuer;
ALTER FUNCTION gobby_agent_auth.reconcile_principal(UUID)
    OWNER TO gobby_agent_issuer;

REVOKE ALL ON FUNCTION gobby_agent_auth.current_project_id() FROM PUBLIC;
REVOKE ALL ON FUNCTION
    gobby_agent_auth.issue_principal(UUID, TEXT, UUID, UUID, UUID, TIMESTAMPTZ, TEXT)
    FROM PUBLIC;
REVOKE ALL ON FUNCTION gobby_agent_auth.rotate_principal(UUID, TIMESTAMPTZ, TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION gobby_agent_auth.revoke_principal(UUID, INTEGER) FROM PUBLIC;
REVOKE ALL ON FUNCTION gobby_agent_auth.reconcile_principal(UUID) FROM PUBLIC;

GRANT EXECUTE ON FUNCTION gobby_agent_auth.current_project_id()
    TO gobby_gcode_capability;
GRANT EXECUTE ON FUNCTION
    gobby_agent_auth.issue_principal(UUID, TEXT, UUID, UUID, UUID, TIMESTAMPTZ, TEXT),
    gobby_agent_auth.rotate_principal(UUID, TIMESTAMPTZ, TEXT),
    gobby_agent_auth.revoke_principal(UUID, INTEGER),
    gobby_agent_auth.reconcile_principal(UUID)
    TO gobby_daemon_runtime;

DO $issuer_source_grants$
BEGIN
    GRANT USAGE ON SCHEMA public TO gobby_agent_issuer;
    IF to_regclass('public.sessions') IS NOT NULL THEN
        GRANT SELECT (id, project_id, agent_run_id) ON public.sessions TO gobby_agent_issuer;
    END IF;
    IF to_regclass('public.agent_runs') IS NOT NULL THEN
        GRANT SELECT (id) ON public.agent_runs TO gobby_agent_issuer;
    END IF;
    IF to_regclass('public.machines') IS NOT NULL THEN
        GRANT SELECT (id) ON public.machines TO gobby_agent_issuer;
    END IF;
END
$issuer_source_grants$;

DO $rls$
DECLARE
    target_schema NAME := current_schema();
    migration_role NAME := current_user;
    table_name TEXT;
    project_expression TEXT;
BEGIN
    FOREACH table_name IN ARRAY ARRAY[
        'projects',
        'code_indexed_projects',
        'code_indexed_project_states',
        'code_indexed_file_states',
        'code_indexed_files',
        'code_symbols',
        'code_imports',
        'code_calls',
        'code_inheritance',
        'code_content_chunks',
        'code_index_projection_cleanup_pending',
        'code_index_prune_dirty_projects'
    ]
    LOOP
        IF to_regclass(format('%I.%I', target_schema, table_name)) IS NULL THEN
            IF table_name = 'code_inheritance' THEN
                CONTINUE;
            END IF;
            RAISE EXCEPTION 'authorization substrate requires relation %.%',
                target_schema,
                table_name;
        END IF;
        IF table_name IN ('projects', 'code_indexed_projects') THEN
            project_expression := 'id = gobby_agent_auth.current_project_id()';
        ELSE
            project_expression := 'project_id = gobby_agent_auth.current_project_id()';
        END IF;
        EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', target_schema, table_name);
        EXECUTE format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY', target_schema, table_name);
        EXECUTE format(
            'DROP POLICY IF EXISTS gobby_agent_project_scope ON %I.%I',
            target_schema,
            table_name
        );
        EXECUTE format(
            'CREATE POLICY gobby_agent_project_scope ON %I.%I TO %I '
            'USING (%s) WITH CHECK (%s)',
            target_schema,
            table_name,
            'gobby_gcode_capability',
            project_expression,
            project_expression
        );
        EXECUTE format(
            'DROP POLICY IF EXISTS gobby_daemon_runtime_access ON %I.%I',
            target_schema,
            table_name
        );
        EXECUTE format(
            'CREATE POLICY gobby_daemon_runtime_access ON %I.%I TO %I '
            'USING (TRUE) WITH CHECK (TRUE)',
            target_schema,
            table_name,
            'gobby_daemon_runtime'
        );
        EXECUTE format(
            'DROP POLICY IF EXISTS gobby_migration_owner_access ON %I.%I',
            target_schema,
            table_name
        );
        EXECUTE format(
            'CREATE POLICY gobby_migration_owner_access ON %I.%I TO %I '
            'USING (TRUE) WITH CHECK (TRUE)',
            target_schema,
            table_name,
            migration_role
        );
    END LOOP;
END
$rls$;

DO $privileges$
DECLARE
    target_schema NAME := current_schema();
    target_database NAME := current_database();
    migration_role NAME := current_user;
BEGIN
    EXECUTE format('REVOKE CONNECT, TEMPORARY ON DATABASE %I FROM PUBLIC', target_database);
    EXECUTE format(
        'GRANT CONNECT ON DATABASE %I TO %I, %I',
        target_database,
        'gobby_gcode_capability',
        'gobby_daemon_runtime'
    );
    EXECUTE format('REVOKE CREATE, USAGE ON SCHEMA %I FROM PUBLIC', target_schema);
    EXECUTE format(
        'GRANT USAGE ON SCHEMA %I TO %I, %I',
        target_schema,
        'gobby_gcode_capability',
        'gobby_daemon_runtime'
    );
    EXECUTE format('REVOKE ALL ON ALL TABLES IN SCHEMA %I FROM PUBLIC', target_schema);
    EXECUTE format('REVOKE ALL ON ALL SEQUENCES IN SCHEMA %I FROM PUBLIC', target_schema);
    EXECUTE format('REVOKE EXECUTE ON ALL FUNCTIONS IN SCHEMA %I FROM PUBLIC', target_schema);
    EXECUTE format(
        'GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA %I TO %I',
        target_schema,
        'gobby_daemon_runtime'
    );
    EXECUTE format(
        'GRANT USAGE, SELECT, UPDATE ON ALL SEQUENCES IN SCHEMA %I TO %I',
        target_schema,
        'gobby_daemon_runtime'
    );
    EXECUTE format(
        'GRANT SELECT (id, name, repo_path) ON %I.projects TO %I',
        target_schema,
        'gobby_gcode_capability'
    );
    EXECUTE format(
        'GRANT SELECT, INSERT, UPDATE, DELETE ON '
        '%I.code_indexed_projects, %I.code_indexed_project_states, '
        '%I.code_indexed_file_states, %I.code_indexed_files, %I.code_symbols, '
        '%I.code_imports, %I.code_calls, %I.code_content_chunks, '
        '%I.code_index_projection_cleanup_pending, %I.code_index_prune_dirty_projects TO %I',
        target_schema,
        target_schema,
        target_schema,
        target_schema,
        target_schema,
        target_schema,
        target_schema,
        target_schema,
        target_schema,
        target_schema,
        'gobby_gcode_capability'
    );
    EXECUTE format(
        'GRANT USAGE, SELECT ON SEQUENCE %I.code_imports_id_seq, %I.code_calls_id_seq TO %I',
        target_schema,
        target_schema,
        'gobby_gcode_capability'
    );
    EXECUTE format(
        'ALTER DEFAULT PRIVILEGES FOR ROLE %I REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC',
        migration_role
    );
    EXECUTE format(
        'ALTER DEFAULT PRIVILEGES FOR ROLE %I IN SCHEMA %I REVOKE ALL ON TABLES FROM PUBLIC',
        migration_role,
        target_schema
    );
    EXECUTE format(
        'ALTER DEFAULT PRIVILEGES FOR ROLE %I IN SCHEMA %I REVOKE ALL ON SEQUENCES FROM PUBLIC',
        migration_role,
        target_schema
    );
    EXECUTE format(
        'ALTER DEFAULT PRIVILEGES FOR ROLE %I IN SCHEMA %I '
        'GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO %I',
        migration_role,
        target_schema,
        'gobby_daemon_runtime'
    );
    EXECUTE format(
        'ALTER DEFAULT PRIVILEGES FOR ROLE %I IN SCHEMA %I '
        'GRANT USAGE, SELECT, UPDATE ON SEQUENCES TO %I',
        migration_role,
        target_schema,
        'gobby_daemon_runtime'
    );
END
$privileges$;

ALTER DEFAULT PRIVILEGES FOR ROLE gobby_agent_issuer
    REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
ALTER DEFAULT PRIVILEGES FOR ROLE gobby_agent_issuer IN SCHEMA gobby_agent_auth
    REVOKE ALL ON TABLES FROM PUBLIC;
ALTER DEFAULT PRIVILEGES FOR ROLE gobby_agent_issuer IN SCHEMA gobby_agent_auth
    REVOKE ALL ON SEQUENCES FROM PUBLIC;

-- Grant the daemon runtime role EXECUTE on public-schema functions.
-- Migration 369 revoked EXECUTE from PUBLIC while granting the runtime role
-- only table/sequence DML, so trigger-invoked functions (e.g.
-- refresh_task_state_bucket via the tasks-table trigger) failed with
-- InsufficientPrivilege once the daemon pool assumed gobby_daemon_runtime.
-- The capability role is untouched: its tables carry no triggers and its
-- only function surface is gobby_agent_auth.current_project_id().

GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO gobby_daemon_runtime;

DO $default_execute$
BEGIN
    EXECUTE format(
        'ALTER DEFAULT PRIVILEGES FOR ROLE %I IN SCHEMA public '
        'GRANT EXECUTE ON FUNCTIONS TO gobby_daemon_runtime',
        current_user
    );
END
$default_execute$;

-- Managed credential lifecycle metadata and daemon leases.

CREATE TABLE IF NOT EXISTS gobby_agent_auth.daemon_registry (
    machine_id UUID PRIMARY KEY REFERENCES public.machines(id) ON DELETE CASCADE,
    heartbeat_at TIMESTAMPTZ NOT NULL,
    lease_expires_at TIMESTAMPTZ NOT NULL,
    started_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CHECK (lease_expires_at > heartbeat_at)
);

CREATE TABLE IF NOT EXISTS gobby_agent_auth.orphan_revocation_retries (
    role_name NAME PRIMARY KEY,
    revocation_attempts INTEGER NOT NULL DEFAULT 0,
    next_retry_at TIMESTAMPTZ NOT NULL,
    last_failure TEXT NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

ALTER TABLE gobby_agent_auth.principal_bindings
    ADD COLUMN IF NOT EXISTS revocation_requested_at TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS revocation_attempts INTEGER NOT NULL DEFAULT 0,
    ADD COLUMN IF NOT EXISTS next_revocation_retry_at TIMESTAMPTZ,
    ADD COLUMN IF NOT EXISTS last_revocation_failure TEXT,
    ADD COLUMN IF NOT EXISTS predecessor_drain_deadline TIMESTAMPTZ;

ALTER TABLE gobby_agent_auth.principal_audit_events
    DROP CONSTRAINT IF EXISTS principal_audit_events_event_type_check;
ALTER TABLE gobby_agent_auth.principal_audit_events
    ADD CONSTRAINT principal_audit_events_event_type_check
    CHECK (event_type IN ('issue', 'rotate', 'revoke', 'reconcile', 'revoke_retry'));

REVOKE ALL ON gobby_agent_auth.daemon_registry FROM PUBLIC;
REVOKE ALL ON gobby_agent_auth.daemon_registry FROM gobby_daemon_runtime;
REVOKE ALL ON gobby_agent_auth.orphan_revocation_retries FROM PUBLIC;
REVOKE ALL ON gobby_agent_auth.orphan_revocation_retries FROM gobby_daemon_runtime;
ALTER TABLE gobby_agent_auth.daemon_registry OWNER TO gobby_agent_issuer;
ALTER TABLE gobby_agent_auth.orphan_revocation_retries OWNER TO gobby_agent_issuer;
GRANT SELECT (id, project_id, agent_run_id, status)
    ON public.sessions TO gobby_agent_issuer;
GRANT SELECT (id, status) ON public.agent_runs TO gobby_agent_issuer;
GRANT SELECT (id, name, repo_path) ON public.projects TO gobby_agent_issuer;

CREATE OR REPLACE FUNCTION gobby_agent_auth.enforce_principal_lifetime()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $function$
BEGIN
    IF NEW.expires_at <= NEW.issued_at THEN
        RAISE EXCEPTION 'managed principal expiry must follow issuance'
            USING ERRCODE = '22023';
    END IF;
    IF NEW.expires_at > NEW.issued_at + INTERVAL '1 hour' THEN
        RAISE EXCEPTION 'managed principal lifetime exceeds one hour'
            USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
END
$function$;

DROP TRIGGER IF EXISTS principal_lifetime_guard
    ON gobby_agent_auth.principal_bindings;
CREATE TRIGGER principal_lifetime_guard
BEFORE INSERT OR UPDATE OF issued_at, expires_at
ON gobby_agent_auth.principal_bindings
FOR EACH ROW
EXECUTE FUNCTION gobby_agent_auth.enforce_principal_lifetime();

-- Single-hop refresh addition: supersedes the one-hour guard above. Agent
-- credential lifetimes derive from the spawn timeout, so the DB-side bound
-- matches MAX_ROLE_LIFETIME (24 hours) while still stopping runaway requests.
CREATE OR REPLACE FUNCTION gobby_agent_auth.enforce_principal_lifetime()
RETURNS TRIGGER
LANGUAGE plpgsql
SET search_path = pg_catalog
AS $function$
BEGIN
    IF NEW.expires_at <= NEW.issued_at THEN
        RAISE EXCEPTION 'managed principal expiry must follow issuance'
            USING ERRCODE = '22023';
    END IF;
    IF NEW.expires_at > NEW.issued_at + INTERVAL '24 hours' THEN
        RAISE EXCEPTION 'managed principal lifetime exceeds 24 hours'
            USING ERRCODE = '22023';
    END IF;
    RETURN NEW;
END
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.heartbeat_daemon(
    p_machine_id UUID,
    p_lease_duration INTERVAL DEFAULT INTERVAL '2 minutes'
) RETURNS UUID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, gobby_agent_auth
AS $function$
DECLARE
    v_now TIMESTAMPTZ := clock_timestamp();
BEGIN
    IF p_lease_duration <= INTERVAL '0 seconds'
       OR p_lease_duration > INTERVAL '5 minutes' THEN
        RAISE EXCEPTION 'daemon lease duration must be between zero and five minutes'
            USING ERRCODE = '22023';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.machines WHERE id = p_machine_id) THEN
        RAISE EXCEPTION 'unknown issuing machine' USING ERRCODE = '23503';
    END IF;

    INSERT INTO gobby_agent_auth.daemon_registry (
        machine_id, heartbeat_at, lease_expires_at, started_at
    ) VALUES (
        p_machine_id, v_now, v_now + p_lease_duration, v_now
    )
    ON CONFLICT (machine_id) DO UPDATE
    SET heartbeat_at = EXCLUDED.heartbeat_at,
        lease_expires_at = EXCLUDED.lease_expires_at;
    RETURN p_machine_id;
END
$function$;

REVOKE ALL ON FUNCTION gobby_agent_auth.enforce_principal_lifetime() FROM PUBLIC;
REVOKE ALL ON FUNCTION gobby_agent_auth.heartbeat_daemon(UUID, INTERVAL) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION gobby_agent_auth.heartbeat_daemon(UUID, INTERVAL)
    TO gobby_daemon_runtime;

CREATE OR REPLACE FUNCTION gobby_agent_auth.revoke_principal(
    requested_execution_id UUID,
    requested_generation INTEGER DEFAULT NULL
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    binding principal_bindings%ROWTYPE;
    revoked_count INTEGER := 0;
    remaining_sessions INTEGER;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(requested_execution_id::TEXT, 0));
    FOR binding IN
        SELECT * FROM principal_bindings
        WHERE managed_execution_id = requested_execution_id
          AND revoked_at IS NULL
          AND (
              requested_generation IS NULL
              OR credential_generation = requested_generation
          )
        ORDER BY credential_generation
        FOR UPDATE
    LOOP
        UPDATE principal_bindings
        SET revocation_requested_at = COALESCE(revocation_requested_at, clock_timestamp()),
            revocation_attempts = revocation_attempts + 1,
            next_revocation_retry_at = NULL,
            last_revocation_failure = NULL
        WHERE id = binding.id;

        IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = binding.role_name) THEN
            EXECUTE format('ALTER ROLE %I NOLOGIN', binding.role_name);
            EXECUTE format(
                'REVOKE %I FROM %I',
                'gobby_gcode_capability',
                binding.role_name
            );
            PERFORM pg_terminate_backend(pid, 5000)
            FROM pg_stat_activity
            WHERE usename = binding.role_name::TEXT
              AND pid <> pg_backend_pid();
            SELECT count(*) INTO remaining_sessions
            FROM pg_stat_activity
            WHERE usename = binding.role_name::TEXT;
            IF remaining_sessions <> 0 THEN
                UPDATE principal_bindings
                SET next_revocation_retry_at = clock_timestamp() + INTERVAL '15 seconds',
                    last_revocation_failure = 'active_sessions_remaining'
                WHERE id = binding.id;
                INSERT INTO principal_audit_events (
                    binding_id,
                    event_type,
                    managed_execution_id,
                    role_name,
                    credential_generation,
                    project_id,
                    details
                ) VALUES (
                    binding.id,
                    'revoke_retry',
                    binding.managed_execution_id,
                    binding.role_name,
                    binding.credential_generation,
                    binding.project_id,
                    jsonb_build_object('failure_code', 'active_sessions_remaining')
                );
                RETURN -1;
            END IF;
            EXECUTE format('DROP ROLE %I', binding.role_name);
        END IF;

        UPDATE principal_bindings
        SET revoked_at = clock_timestamp(),
            next_revocation_retry_at = NULL,
            last_revocation_failure = NULL
        WHERE id = binding.id;
        INSERT INTO principal_audit_events (
            binding_id,
            event_type,
            managed_execution_id,
            role_name,
            credential_generation,
            project_id
        ) VALUES (
            binding.id,
            'revoke',
            binding.managed_execution_id,
            binding.role_name,
            binding.credential_generation,
            binding.project_id
        );
        revoked_count := revoked_count + 1;
    END LOOP;
    RETURN revoked_count;
END
$function$;

REVOKE ALL ON FUNCTION gobby_agent_auth.revoke_principal(UUID, INTEGER) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION gobby_agent_auth.revoke_principal(UUID, INTEGER)
    TO gobby_daemon_runtime;

CREATE OR REPLACE FUNCTION gobby_agent_auth.principals_due_for_rotation(
    p_machine_id UUID
)
RETURNS TABLE(
    managed_execution_id UUID,
    role_name NAME,
    credential_generation INTEGER
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = pg_catalog, gobby_agent_auth
AS $function$
    WITH single_active AS (
        SELECT pb.managed_execution_id
        FROM gobby_agent_auth.principal_bindings AS pb
        WHERE pb.issuing_machine_id = p_machine_id
          AND pb.revoked_at IS NULL
          AND pb.expires_at > clock_timestamp()
        GROUP BY pb.managed_execution_id
        HAVING count(*) = 1
    )
    SELECT pb.managed_execution_id, pb.role_name, pb.credential_generation
    FROM gobby_agent_auth.principal_bindings AS pb
    JOIN single_active AS active USING (managed_execution_id)
    WHERE pb.revoked_at IS NULL
      AND pb.revocation_requested_at IS NULL
      AND pb.issued_at <= clock_timestamp() - INTERVAL '45 minutes'
      AND pb.expires_at > clock_timestamp()
    ORDER BY pb.managed_execution_id
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.rotate_principal_if_generation(
    p_execution_id UUID,
    p_expected_generation INTEGER,
    p_expires_at TIMESTAMPTZ,
    p_password TEXT
)
RETURNS TABLE(role_name NAME, credential_generation INTEGER)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    v_current_generation INTEGER;
    v_role_name NAME;
    v_generation INTEGER;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(p_execution_id::TEXT, 0));
    SELECT max(pb.credential_generation) INTO v_current_generation
    FROM principal_bindings AS pb
    WHERE pb.managed_execution_id = p_execution_id
      AND pb.revoked_at IS NULL
      AND pb.expires_at > clock_timestamp();
    IF v_current_generation IS DISTINCT FROM p_expected_generation THEN
        RETURN;
    END IF;

    SELECT rotated.role_name, rotated.credential_generation
    INTO v_role_name, v_generation
    FROM rotate_principal(p_execution_id, p_expires_at, p_password) AS rotated;

UPDATE principal_bindings AS predecessor
SET revocation_requested_at = statement_timestamp(),
predecessor_drain_deadline = statement_timestamp() + INTERVAL '5 minutes'
    WHERE predecessor.managed_execution_id = p_execution_id
      AND predecessor.credential_generation = p_expected_generation
      AND predecessor.revoked_at IS NULL;
    RETURN QUERY SELECT v_role_name, v_generation;
END
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.cancel_principal_rotation(
    p_execution_id UUID,
    p_predecessor_generation INTEGER,
    p_successor_generation INTEGER
)
RETURNS VOID
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
AS $function$
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(p_execution_id::TEXT, 0));
    IF EXISTS (
        SELECT 1 FROM principal_bindings
        WHERE managed_execution_id = p_execution_id
          AND credential_generation = p_successor_generation
          AND revoked_at IS NOT NULL
    ) THEN
        UPDATE principal_bindings
        SET revocation_requested_at = NULL,
            predecessor_drain_deadline = NULL,
            next_revocation_retry_at = NULL,
            last_revocation_failure = NULL
        WHERE managed_execution_id = p_execution_id
          AND credential_generation = p_predecessor_generation
          AND revoked_at IS NULL;
    END IF;
END
$function$;

REVOKE ALL ON FUNCTION gobby_agent_auth.principals_due_for_rotation(UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION gobby_agent_auth.rotate_principal_if_generation(
    UUID, INTEGER, TIMESTAMPTZ, TEXT
) FROM PUBLIC;
REVOKE ALL ON FUNCTION gobby_agent_auth.cancel_principal_rotation(
    UUID, INTEGER, INTEGER
) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION gobby_agent_auth.principals_due_for_rotation(UUID)
    TO gobby_daemon_runtime;
GRANT EXECUTE ON FUNCTION gobby_agent_auth.rotate_principal_if_generation(
    UUID, INTEGER, TIMESTAMPTZ, TEXT
) TO gobby_daemon_runtime;
GRANT EXECUTE ON FUNCTION gobby_agent_auth.cancel_principal_rotation(
    UUID, INTEGER, INTEGER
) TO gobby_daemon_runtime;

CREATE OR REPLACE FUNCTION gobby_agent_auth.reconcile_daemon(
    p_machine_id UUID
)
RETURNS INTEGER
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    candidate RECORD;
    orphan_role RECORD;
    result_count INTEGER;
    remaining_sessions INTEGER;
    reconciled_count INTEGER := 0;
    retry_pending BOOLEAN := FALSE;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended('gobby-agent-auth-reconcile', 0));
    IF NOT EXISTS (SELECT 1 FROM public.machines WHERE id = p_machine_id) THEN
        RAISE EXCEPTION 'unknown reconciling machine' USING ERRCODE = '23503';
    END IF;

    FOR candidate IN
        SELECT pb.managed_execution_id, pb.credential_generation
        FROM principal_bindings AS pb
        LEFT JOIN daemon_registry AS daemon
          ON daemon.machine_id = pb.issuing_machine_id
        LEFT JOIN public.agent_runs AS run
          ON run.id = pb.agent_run_id
        WHERE pb.revoked_at IS NULL
          AND (
              pb.issuing_machine_id = p_machine_id
              OR daemon.lease_expires_at IS NULL
              OR daemon.lease_expires_at <= clock_timestamp()
          )
          AND (
              pb.expires_at <= clock_timestamp()
              OR pb.revocation_requested_at IS NOT NULL
              OR (
                  pb.owner_kind = 'agent_run'
                  AND run.status IN ('success', 'error', 'timeout', 'cancelled')
              )
          )
        ORDER BY pb.managed_execution_id, pb.credential_generation
    LOOP
        result_count := revoke_principal(
            candidate.managed_execution_id,
            candidate.credential_generation
        );
        IF result_count > 0 THEN
            reconciled_count := reconciled_count + result_count;
        ELSIF result_count < 0 THEN
            retry_pending := TRUE;
        END IF;
    END LOOP;

    FOR orphan_role IN
        SELECT roles.rolname
        FROM pg_roles AS roles
        WHERE roles.rolname ~ '^gobby_agent_[0-9a-f]{32}_[1-9][0-9]*$'
          AND NOT EXISTS (
              SELECT 1 FROM principal_bindings AS binding
              WHERE binding.role_name = roles.rolname
          )
        ORDER BY roles.rolname
    LOOP
        EXECUTE format('ALTER ROLE %I NOLOGIN', orphan_role.rolname);
        PERFORM pg_terminate_backend(pid, 5000)
        FROM pg_stat_activity
        WHERE usename = orphan_role.rolname::TEXT
          AND pid <> pg_backend_pid();
        SELECT count(*) INTO remaining_sessions
        FROM pg_stat_activity
        WHERE usename = orphan_role.rolname::TEXT;
        IF remaining_sessions <> 0 THEN
            INSERT INTO orphan_revocation_retries (
                role_name, revocation_attempts, next_retry_at, last_failure, updated_at
            ) VALUES (
                orphan_role.rolname, 1, clock_timestamp() + INTERVAL '15 seconds',
                'active_sessions_remaining', clock_timestamp()
            )
            ON CONFLICT (role_name) DO UPDATE
            SET revocation_attempts = orphan_revocation_retries.revocation_attempts + 1,
                next_retry_at = EXCLUDED.next_retry_at,
                last_failure = EXCLUDED.last_failure,
                updated_at = EXCLUDED.updated_at;
            retry_pending := TRUE;
            CONTINUE;
        END IF;
        EXECUTE format('DROP ROLE %I', orphan_role.rolname);
        DELETE FROM orphan_revocation_retries
        WHERE role_name = orphan_role.rolname;
        reconciled_count := reconciled_count + 1;
    END LOOP;
    IF retry_pending THEN
        RETURN -1;
    END IF;
    RETURN reconciled_count;
END
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.managed_execution_is_login_capable(
    p_execution_id UUID
)
RETURNS BOOLEAN
LANGUAGE sql
SECURITY DEFINER
SET search_path = pg_catalog, gobby_agent_auth
AS $function$
    SELECT EXISTS (
        SELECT 1
        FROM gobby_agent_auth.principal_bindings AS binding
        JOIN pg_catalog.pg_roles AS role ON role.rolname = binding.role_name
        WHERE binding.managed_execution_id = p_execution_id
          AND binding.revoked_at IS NULL
          AND binding.expires_at > clock_timestamp()
          AND role.rolcanlogin
    )
$function$;

REVOKE ALL ON FUNCTION gobby_agent_auth.reconcile_daemon(UUID) FROM PUBLIC;
REVOKE ALL ON FUNCTION gobby_agent_auth.managed_execution_is_login_capable(UUID)
    FROM PUBLIC;
GRANT EXECUTE ON FUNCTION gobby_agent_auth.reconcile_daemon(UUID)
    TO gobby_daemon_runtime;
GRANT EXECUTE ON FUNCTION gobby_agent_auth.managed_execution_is_login_capable(UUID)
    TO gobby_daemon_runtime;

CREATE OR REPLACE FUNCTION gobby_agent_auth.resolve_tool_session(
    p_session_id UUID
)
RETURNS TABLE(session_id UUID, project_id UUID, repo_path TEXT)
LANGUAGE sql
SECURITY DEFINER
SET search_path = pg_catalog
AS $function$
    SELECT session.id, project.id, project.repo_path
    FROM public.sessions AS session
    JOIN public.projects AS project ON project.id = session.project_id
    WHERE session.id = p_session_id
      AND COALESCE(session.status, 'active') NOT IN ('expired', 'deleted')
$function$;

REVOKE ALL ON FUNCTION gobby_agent_auth.resolve_tool_session(UUID) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION gobby_agent_auth.resolve_tool_session(UUID)
    TO gobby_daemon_runtime;

CREATE OR REPLACE FUNCTION gobby_agent_auth.issue_tool_principal(
    p_execution_id UUID,
    p_session_id UUID,
    p_machine_id UUID,
    p_expires_at TIMESTAMPTZ,
    p_password TEXT
)
RETURNS TABLE(role_name NAME, credential_generation INTEGER)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    v_project_id UUID;
    v_workspace_count INTEGER;
    v_workspace_path TEXT;
    v_overlay_project_id UUID;
    v_role_name NAME;
    v_binding_id UUID;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(p_execution_id::TEXT, 0));
    IF p_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'managed principal expiry must be in the future'
            USING ERRCODE = '22023';
    END IF;
    IF p_password IS NULL OR p_password = '' THEN
        RAISE EXCEPTION 'managed principal password must not be empty'
            USING ERRCODE = '22023';
    END IF;
    IF EXISTS (
        SELECT 1 FROM principal_bindings
        WHERE managed_execution_id = p_execution_id
    ) THEN
        RAISE EXCEPTION 'managed execution already has a principal binding'
            USING ERRCODE = '23505';
    END IF;
    SELECT session.project_id INTO v_project_id
    FROM public.sessions AS session
    WHERE session.id = p_session_id
      AND COALESCE(session.status, 'active') NOT IN ('expired', 'deleted');
    IF NOT FOUND THEN
        RAISE EXCEPTION 'managed principal session does not exist'
            USING ERRCODE = '23503';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.machines WHERE id = p_machine_id) THEN
        RAISE EXCEPTION 'managed principal issuing machine does not exist'
            USING ERRCODE = '23503';
    END IF;

    SELECT count(*), min(workspace.workspace_path)
    INTO v_workspace_count, v_workspace_path
    FROM (
        SELECT worktree.worktree_path AS workspace_path
        FROM public.worktrees AS worktree
        WHERE worktree.agent_session_id = p_session_id
          AND worktree.project_id = v_project_id
          AND worktree.machine_id = p_machine_id
        UNION ALL
        SELECT clone.clone_path AS workspace_path
        FROM public.clones AS clone
        WHERE clone.agent_session_id = p_session_id
          AND clone.project_id = v_project_id
          AND clone.machine_id = p_machine_id
    ) AS workspace;
    IF v_workspace_count > 1 THEN
        RAISE EXCEPTION 'tool-chat principal session has multiple isolation workspaces'
            USING ERRCODE = '23514';
    END IF;
    IF v_workspace_count = 1 THEN
        v_overlay_project_id := code_index_project_id(v_workspace_path);
    END IF;

    v_role_name := (
        'gobby_agent_' || replace(p_execution_id::TEXT, '-', '') || '_1'
    )::NAME;
    EXECUTE format(
        'CREATE ROLE %I LOGIN PASSWORD %L VALID UNTIL %L INHERIT '
        'NOSUPERUSER NOCREATEROLE NOCREATEDB NOREPLICATION NOBYPASSRLS',
        v_role_name,
        p_password,
        p_expires_at
    );
    EXECUTE format(
        'GRANT %I TO %I WITH ADMIN FALSE, INHERIT TRUE, SET FALSE',
        'gobby_gcode_capability',
        v_role_name
    );
    INSERT INTO principal_bindings (
        role_name, owner_kind, managed_execution_id, agent_run_id,
        session_id, project_id, code_overlay_project_id, issuing_machine_id, expires_at,
        credential_generation
    ) VALUES (
        v_role_name, 'tool_chat', p_execution_id, NULL,
        p_session_id, v_project_id, v_overlay_project_id, p_machine_id, p_expires_at, 1
    ) RETURNING id INTO v_binding_id;
    INSERT INTO principal_audit_events (
        binding_id, event_type, managed_execution_id, role_name,
        credential_generation, project_id
    ) VALUES (
        v_binding_id, 'issue', p_execution_id, v_role_name, 1, v_project_id
    );
    RETURN QUERY SELECT v_role_name, 1;
END
$function$;

