            USING ERRCODE = '42501';
    END IF;
    RETURN bound_machine_id;
END
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.issue_principal(
    requested_execution_id UUID,
    requested_owner_kind TEXT,
    requested_session_id UUID,
    requested_agent_run_id UUID,
    requested_machine_id UUID,
    requested_expires_at TIMESTAMPTZ,
    requested_password TEXT
)
RETURNS TABLE(role_name NAME, credential_generation INTEGER)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    resolved_project_id UUID;
    resolved_agent_run_id UUID;
    resolved_run_machine_id UUID;
    resolved_worktree_id UUID;
    resolved_clone_id UUID;
    resolved_workspace_path TEXT;
    resolved_overlay_project_id UUID;
    derived_role_name NAME;
    binding_id UUID;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(requested_execution_id::TEXT, 0));
    IF requested_owner_kind NOT IN ('agent_run', 'tool_chat') THEN
        RAISE EXCEPTION 'unsupported managed principal owner kind'
            USING ERRCODE = '22023';
    END IF;
    IF requested_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'managed principal expiry must be in the future'
            USING ERRCODE = '22023';
    END IF;
    IF requested_password IS NULL OR requested_password = '' THEN
        RAISE EXCEPTION 'managed principal password must not be empty'
            USING ERRCODE = '22023';
    END IF;
    IF EXISTS (
        SELECT 1 FROM principal_bindings
        WHERE managed_execution_id = requested_execution_id
    ) THEN
        RAISE EXCEPTION 'managed execution already has a principal binding'
            USING ERRCODE = '23505';
    END IF;

    SELECT project_id, agent_run_id
    INTO resolved_project_id, resolved_agent_run_id
    FROM public.sessions
    WHERE id = requested_session_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'managed principal session does not exist'
            USING ERRCODE = '23503';
    END IF;
    IF resolved_agent_run_id IS DISTINCT FROM requested_agent_run_id THEN
        RAISE EXCEPTION 'managed principal agent run does not match its session'
            USING ERRCODE = '23503';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM public.machines WHERE id = requested_machine_id) THEN
        RAISE EXCEPTION 'managed principal issuing machine does not exist'
            USING ERRCODE = '23503';
    END IF;

    IF requested_owner_kind = 'agent_run' THEN
        IF requested_agent_run_id IS NULL THEN
            RAISE EXCEPTION 'agent-run principal requires an agent run'
                USING ERRCODE = '23503';
        END IF;
        SELECT machine_id, worktree_id, clone_id
        INTO resolved_run_machine_id, resolved_worktree_id, resolved_clone_id
        FROM public.agent_runs
        WHERE id = requested_agent_run_id;
        IF NOT FOUND THEN
            RAISE EXCEPTION 'managed principal agent run does not exist'
                USING ERRCODE = '23503';
        END IF;
        IF resolved_run_machine_id IS DISTINCT FROM requested_machine_id THEN
            RAISE EXCEPTION 'managed principal agent run belongs to another machine'
                USING ERRCODE = '23503';
        END IF;
        IF resolved_worktree_id IS NOT NULL AND resolved_clone_id IS NOT NULL THEN
            RAISE EXCEPTION 'managed principal agent run has multiple isolation workspaces'
                USING ERRCODE = '23514';
        END IF;
        IF resolved_worktree_id IS NOT NULL THEN
            SELECT worktree_path INTO resolved_workspace_path
            FROM public.worktrees
            WHERE id = resolved_worktree_id
              AND project_id = resolved_project_id
              AND machine_id = requested_machine_id;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'managed principal worktree does not match project and machine'
                    USING ERRCODE = '23503';
            END IF;
        ELSIF resolved_clone_id IS NOT NULL THEN
            SELECT clone_path INTO resolved_workspace_path
            FROM public.clones
            WHERE id = resolved_clone_id
              AND project_id = resolved_project_id
              AND machine_id = requested_machine_id;
            IF NOT FOUND THEN
                RAISE EXCEPTION 'managed principal clone does not match project and machine'
                    USING ERRCODE = '23503';
            END IF;
        END IF;
        IF resolved_workspace_path IS NOT NULL THEN
            resolved_overlay_project_id := code_index_project_id(resolved_workspace_path);
        END IF;
    END IF;

    derived_role_name := (
        'gobby_agent_' || replace(requested_execution_id::TEXT, '-', '') || '_1'
    )::NAME;
    EXECUTE format(
        'CREATE ROLE %I LOGIN PASSWORD %L VALID UNTIL %L INHERIT '
        'NOSUPERUSER NOCREATEROLE NOCREATEDB NOREPLICATION NOBYPASSRLS',
        derived_role_name,
        requested_password,
        requested_expires_at
    );
    EXECUTE format(
        'GRANT %I TO %I WITH ADMIN FALSE, INHERIT TRUE, SET FALSE',
        'gobby_gcode_capability',
        derived_role_name
    );

    INSERT INTO principal_bindings (
        role_name,
        owner_kind,
        managed_execution_id,
        agent_run_id,
        session_id,
        project_id,
        code_overlay_project_id,
        issuing_machine_id,
        expires_at,
        credential_generation
    ) VALUES (
        derived_role_name,
        requested_owner_kind,
        requested_execution_id,
        requested_agent_run_id,
        requested_session_id,
        resolved_project_id,
        resolved_overlay_project_id,
        requested_machine_id,
        requested_expires_at,
        1
    ) RETURNING id INTO binding_id;

    INSERT INTO principal_audit_events (
        binding_id,
        event_type,
        managed_execution_id,
        role_name,
        credential_generation,
        project_id
    ) VALUES (
        binding_id,
        'issue',
        requested_execution_id,
        derived_role_name,
        1,
        resolved_project_id
    );
    RETURN QUERY SELECT derived_role_name, 1;
END
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.rotate_principal(
    requested_execution_id UUID,
    requested_expires_at TIMESTAMPTZ,
    requested_password TEXT
)
RETURNS TABLE(role_name NAME, credential_generation INTEGER)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    source_binding principal_bindings%ROWTYPE;
    active_count INTEGER;
    next_generation INTEGER;
    derived_role_name NAME;
    binding_id UUID;
BEGIN
    PERFORM pg_advisory_xact_lock(hashtextextended(requested_execution_id::TEXT, 0));
    IF requested_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'managed principal expiry must be in the future'
            USING ERRCODE = '22023';
    END IF;
    IF requested_password IS NULL OR requested_password = '' THEN
        RAISE EXCEPTION 'managed principal password must not be empty'
            USING ERRCODE = '22023';
    END IF;
    SELECT count(*) INTO active_count
    FROM principal_bindings
    WHERE managed_execution_id = requested_execution_id
      AND revoked_at IS NULL
      AND expires_at > clock_timestamp();
    IF active_count <> 1 THEN
        RAISE EXCEPTION 'rotation requires exactly one active principal binding'
            USING ERRCODE = '42501';
    END IF;
    SELECT * INTO STRICT source_binding
    FROM principal_bindings
    WHERE managed_execution_id = requested_execution_id
      AND revoked_at IS NULL
      AND expires_at > clock_timestamp();
    SELECT COALESCE(max(pb.credential_generation), 0) + 1
    INTO next_generation
    FROM principal_bindings pb
    WHERE pb.managed_execution_id = requested_execution_id;

    derived_role_name := (
        'gobby_agent_' || replace(requested_execution_id::TEXT, '-', '') || '_' || next_generation
    )::NAME;
    EXECUTE format(
        'CREATE ROLE %I LOGIN PASSWORD %L VALID UNTIL %L INHERIT '
        'NOSUPERUSER NOCREATEROLE NOCREATEDB NOREPLICATION NOBYPASSRLS',
        derived_role_name,
        requested_password,
        requested_expires_at
    );
    EXECUTE format(
        'GRANT %I TO %I WITH ADMIN FALSE, INHERIT TRUE, SET FALSE',
        'gobby_gcode_capability',
        derived_role_name
    );

    INSERT INTO principal_bindings (
        role_name,
        owner_kind,
        managed_execution_id,
        agent_run_id,
        session_id,
        project_id,
        code_overlay_project_id,
        issuing_machine_id,
        expires_at,
        credential_generation
    ) VALUES (
        derived_role_name,
        source_binding.owner_kind,
        requested_execution_id,
        source_binding.agent_run_id,
        source_binding.session_id,
        source_binding.project_id,
        source_binding.code_overlay_project_id,
        source_binding.issuing_machine_id,
        requested_expires_at,
        next_generation
    ) RETURNING id INTO binding_id;

    INSERT INTO principal_audit_events (
        binding_id,
        event_type,
        managed_execution_id,
        role_name,
        credential_generation,
        project_id
    ) VALUES (
        binding_id,
        'rotate',
        requested_execution_id,
        derived_role_name,
        next_generation,
        source_binding.project_id
    );
    RETURN QUERY SELECT derived_role_name, next_generation;
END
$function$;

ALTER FUNCTION gobby_agent_auth.code_index_project_id(TEXT)
    OWNER TO gobby_agent_issuer;
ALTER FUNCTION gobby_agent_auth.current_code_overlay_project_id()
    OWNER TO gobby_agent_issuer;
ALTER FUNCTION gobby_agent_auth.current_machine_id()
    OWNER TO gobby_agent_issuer;

REVOKE ALL ON FUNCTION gobby_agent_auth.code_index_project_id(TEXT) FROM PUBLIC;
REVOKE ALL ON FUNCTION
    gobby_agent_auth.current_code_overlay_project_id(),
    gobby_agent_auth.current_machine_id()
    FROM PUBLIC;
GRANT EXECUTE ON FUNCTION
    gobby_agent_auth.current_code_overlay_project_id(),
    gobby_agent_auth.current_machine_id()
    TO gobby_gcode_capability;

DO $gcode_rls$
DECLARE
    target_schema NAME := current_schema();
    table_name TEXT;
    project_column TEXT;
    read_expression TEXT;
    write_expression TEXT;
    machine_expression TEXT;
BEGIN
    FOREACH table_name IN ARRAY ARRAY[
        'code_indexed_projects',
        'code_indexed_project_states',
        'code_indexed_file_states',
        'code_indexed_files',
        'code_symbols',
        'code_imports',
        'code_calls',
        'code_inheritance',
        'code_content_chunks',
        'code_index_projection_cleanup_pending',
        'code_index_prune_dirty_projects'
    ]
    LOOP
        IF to_regclass(format('%I.%I', target_schema, table_name)) IS NULL THEN
            IF table_name = 'code_inheritance' THEN
                CONTINUE;
            END IF;
            RAISE EXCEPTION 'gcode authorization requires relation %.%',
                target_schema,
                table_name;
        END IF;
        IF table_name = 'code_indexed_projects' THEN
            project_column := 'id';
        ELSE
            project_column := 'project_id';
        END IF;
        read_expression := format(
            '(%1$I = gobby_agent_auth.current_project_id() OR '
            '%1$I = gobby_agent_auth.current_code_overlay_project_id())',
            project_column
        );
        write_expression := format(
            '%I = COALESCE(gobby_agent_auth.current_code_overlay_project_id(), '
            'gobby_agent_auth.current_project_id())',
            project_column
        );
        IF table_name IN (
            'code_indexed_project_states',
            'code_indexed_file_states',
            'code_index_prune_dirty_projects'
        ) THEN
            machine_expression :=
                'machine_id = gobby_agent_auth.current_machine_id()';
            read_expression := format(
                '(%s AND %s)',
                read_expression,
                machine_expression
            );
            write_expression := format(
                '(%s AND %s)',
                write_expression,
                machine_expression
            );
        END IF;

        EXECUTE format(
            'DROP POLICY IF EXISTS gobby_agent_project_scope ON %I.%I',
            target_schema,
            table_name
        );
        EXECUTE format(
            'DROP POLICY IF EXISTS gobby_gcode_project_read ON %I.%I',
            target_schema,
            table_name
        );
        EXECUTE format(
            'DROP POLICY IF EXISTS gobby_gcode_project_insert ON %I.%I',
            target_schema,
            table_name
        );
        EXECUTE format(
            'DROP POLICY IF EXISTS gobby_gcode_project_update ON %I.%I',
            target_schema,
            table_name
        );
        EXECUTE format(
            'DROP POLICY IF EXISTS gobby_gcode_project_delete ON %I.%I',
            target_schema,
            table_name
        );
        EXECUTE format(
            'CREATE POLICY gobby_gcode_project_read ON %I.%I '
            'FOR SELECT TO %I USING (%s)',
            target_schema,
            table_name,
            'gobby_gcode_capability',
            read_expression
        );
        EXECUTE format(
            'CREATE POLICY gobby_gcode_project_insert ON %I.%I '
            'FOR INSERT TO %I WITH CHECK (%s)',
            target_schema,
            table_name,
            'gobby_gcode_capability',
            write_expression
        );
        EXECUTE format(
            'CREATE POLICY gobby_gcode_project_update ON %I.%I '
            'FOR UPDATE TO %I USING (%s) WITH CHECK (%s)',
            target_schema,
            table_name,
            'gobby_gcode_capability',
            write_expression,
            write_expression
        );
        EXECUTE format(
            'CREATE POLICY gobby_gcode_project_delete ON %I.%I '
            'FOR DELETE TO %I USING (%s)',
            target_schema,
            table_name,
            'gobby_gcode_capability',
            write_expression
        );
    END LOOP;
END
$gcode_rls$;

CREATE TABLE IF NOT EXISTS deployment_runtime (
    deployment_token TEXT PRIMARY KEY,
    fencing_epoch BIGINT NOT NULL DEFAULT 0,
    grant_signing_secret TEXT NOT NULL,
    epoch_updated_at TIMESTAMPTZ
);

GRANT SELECT,INSERT,UPDATE ON TABLE deployment_runtime TO gobby_daemon_runtime;
REVOKE ALL ON TABLE deployment_runtime FROM PUBLIC;

ALTER TABLE gobby_agent_auth.principal_bindings DROP CONSTRAINT IF EXISTS principal_bindings_owner_kind_check;
ALTER TABLE gobby_agent_auth.principal_bindings ADD CONSTRAINT principal_bindings_owner_kind_check CHECK (owner_kind IN ('agent_run', 'tool_chat', 'interactive'));
ALTER TABLE gobby_agent_auth.principal_bindings ADD COLUMN IF NOT EXISTS deployment_token TEXT;

DROP INDEX IF EXISTS gobby_agent_auth.uq_interactive_principal_active;
CREATE UNIQUE INDEX IF NOT EXISTS uq_interactive_principal_active
ON gobby_agent_auth.principal_bindings(deployment_token, issuing_machine_id, project_id)
WHERE owner_kind = 'interactive'
  AND revoked_at IS NULL
  AND predecessor_drain_deadline IS NULL
  AND deployment_token IS NOT NULL;

CREATE TABLE IF NOT EXISTS gobby_agent_auth.interactive_credential_material (
    deployment_token TEXT NOT NULL,
    machine_id UUID NOT NULL,
    project_id UUID NOT NULL,
    credential_generation INTEGER NOT NULL CHECK (credential_generation > 0),
    ciphertext TEXT NOT NULL,
    aad_identity TEXT NOT NULL,
    created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    PRIMARY KEY (deployment_token, machine_id, project_id, credential_generation)
);

DROP FUNCTION IF EXISTS gobby_agent_auth.issue_or_reuse_interactive_principal(
    TEXT, UUID, UUID, UUID, TIMESTAMPTZ, TEXT
);
CREATE OR REPLACE FUNCTION gobby_agent_auth.issue_or_reuse_interactive_principal(
    requested_deployment_token TEXT,
    requested_machine_id UUID,
    requested_project_id UUID,
    requested_session_id UUID,
    requested_expires_at TIMESTAMPTZ,
    requested_password TEXT
)
RETURNS TABLE(
    role_name NAME,
    credential_generation INTEGER,
    reused BOOLEAN,
    managed_execution_id UUID
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    existing_binding principal_bindings%ROWTYPE;
    derived_role_name NAME;
    next_generation INTEGER;
    binding_id UUID;
    token_slug TEXT;
BEGIN
    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            requested_deployment_token || requested_machine_id::TEXT || requested_project_id::TEXT,
            0
        )
    );
    IF requested_deployment_token IS NULL OR requested_deployment_token = '' THEN
        RAISE EXCEPTION 'interactive principal requires a deployment token'
            USING ERRCODE = '22023';
    END IF;
    IF requested_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'managed principal expiry must be in the future'
            USING ERRCODE = '22023';
    END IF;
    IF requested_password IS NULL OR requested_password = '' THEN
        RAISE EXCEPTION 'managed principal password must not be empty'
            USING ERRCODE = '22023';
    END IF;

    SELECT *
      INTO existing_binding
      FROM principal_bindings
     WHERE owner_kind = 'interactive'
       AND deployment_token = requested_deployment_token
       AND issuing_machine_id = requested_machine_id
       AND project_id = requested_project_id
       AND revoked_at IS NULL
       AND predecessor_drain_deadline IS NULL
       AND expires_at > clock_timestamp()
     ORDER BY credential_generation DESC
     LIMIT 1;
    IF FOUND THEN
        RETURN QUERY SELECT existing_binding.role_name,
            existing_binding.credential_generation, TRUE,
            existing_binding.managed_execution_id;
        RETURN;
    END IF;

    SELECT COALESCE(MAX(pb.credential_generation), 0) + 1
      INTO next_generation
      FROM principal_bindings AS pb
     WHERE pb.owner_kind = 'interactive'
       AND pb.deployment_token = requested_deployment_token
       AND pb.issuing_machine_id = requested_machine_id
       AND pb.project_id = requested_project_id;
    token_slug := regexp_replace(requested_deployment_token, '[^a-zA-Z0-9]', '', 'g');
    derived_role_name := (
        'gobby_ix_'
        || substr(token_slug, 1, 8)
        || '_'
        || substr(replace(requested_machine_id::TEXT, '-', ''), 1, 8)
        || '_'
        || substr(replace(requested_project_id::TEXT, '-', ''), 1, 8)
        || '_'
        || next_generation::TEXT
    )::NAME;
    EXECUTE format(
        'CREATE ROLE %I LOGIN PASSWORD %L VALID UNTIL %L INHERIT '
        'NOSUPERUSER NOCREATEROLE NOCREATEDB NOREPLICATION NOBYPASSRLS',
        derived_role_name,
        requested_password,
        requested_expires_at
    );
    EXECUTE format(
        'GRANT %I TO %I WITH ADMIN FALSE, INHERIT TRUE, SET FALSE',
        'gobby_gcode_capability',
        derived_role_name
    );

    INSERT INTO principal_bindings (
        role_name,
        owner_kind,
        managed_execution_id,
        session_id,
        project_id,
        issuing_machine_id,
        deployment_token,
        expires_at,
        credential_generation
    ) VALUES (
        derived_role_name,
        'interactive',
        gen_random_uuid(),
        requested_session_id,
        requested_project_id,
        requested_machine_id,
        requested_deployment_token,
        requested_expires_at,
        next_generation
    ) RETURNING id INTO binding_id;

    INSERT INTO principal_audit_events (
        binding_id,
        event_type,
        managed_execution_id,
        role_name,
        credential_generation,
        project_id
    ) VALUES (
        binding_id,
        'issue',
        (SELECT pb.managed_execution_id FROM principal_bindings AS pb WHERE pb.id = binding_id),
        derived_role_name,
        next_generation,
        requested_project_id
    );
    RETURN QUERY SELECT derived_role_name, next_generation, FALSE,
        (SELECT pb.managed_execution_id FROM principal_bindings AS pb WHERE pb.id = binding_id);
END
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.load_interactive_credential_material(
    requested_deployment_token TEXT,
    requested_machine_id UUID,
    requested_project_id UUID,
    requested_generation INTEGER
)
RETURNS TABLE(ciphertext TEXT, aad_identity TEXT)
LANGUAGE sql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
AS $function$
    SELECT ciphertext, aad_identity
      FROM interactive_credential_material
     WHERE deployment_token = requested_deployment_token
       AND machine_id = requested_machine_id
       AND project_id = requested_project_id
       AND credential_generation = requested_generation
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.lookup_interactive_principal(
    requested_deployment_token TEXT,
    requested_machine_id UUID,
    requested_project_id UUID,
    requested_generation INTEGER
)
RETURNS TABLE(
    managed_execution_id UUID,
    role_name NAME,
    credential_generation INTEGER,
    revoked_at TIMESTAMPTZ
)
LANGUAGE sql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
AS $function$
    SELECT managed_execution_id, role_name, credential_generation, revoked_at
      FROM principal_bindings
     WHERE owner_kind = 'interactive'
       AND deployment_token = requested_deployment_token
       AND issuing_machine_id = requested_machine_id
       AND project_id = requested_project_id
       AND (
           requested_generation IS NULL
           OR credential_generation = requested_generation
       )
     ORDER BY credential_generation DESC
     LIMIT 1
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.rotate_interactive_principal(
    requested_deployment_token TEXT,
    requested_machine_id UUID,
    requested_project_id UUID,
    requested_session_id UUID,
    requested_expires_at TIMESTAMPTZ,
    requested_password TEXT,
    requested_drain_until TIMESTAMPTZ
)
RETURNS TABLE(
    role_name NAME,
    credential_generation INTEGER,
    managed_execution_id UUID
)
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
SET createrole_self_grant = ''
AS $function$
DECLARE
    existing_binding principal_bindings%ROWTYPE;
    derived_role_name NAME;
    next_generation INTEGER;
    binding_id UUID;
    token_slug TEXT;
    drain_until TIMESTAMPTZ;
BEGIN
    PERFORM pg_advisory_xact_lock(
        hashtextextended(
            requested_deployment_token || requested_machine_id::TEXT || requested_project_id::TEXT,
            0
        )
    );
    IF requested_expires_at <= clock_timestamp() THEN
        RAISE EXCEPTION 'managed principal expiry must be in the future'
            USING ERRCODE = '22023';
    END IF;
    IF requested_password IS NULL OR requested_password = '' THEN
        RAISE EXCEPTION 'managed principal password must not be empty'
            USING ERRCODE = '22023';
    END IF;
    SELECT *
      INTO existing_binding
      FROM principal_bindings
     WHERE owner_kind = 'interactive'
       AND deployment_token = requested_deployment_token
       AND issuing_machine_id = requested_machine_id
       AND project_id = requested_project_id
       AND revoked_at IS NULL
       AND predecessor_drain_deadline IS NULL
     ORDER BY credential_generation DESC
     LIMIT 1;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'interactive rotation requires an active principal'
            USING ERRCODE = '42501';
    END IF;
    drain_until := GREATEST(requested_drain_until, clock_timestamp() + INTERVAL '1 second');
    UPDATE principal_bindings
       SET predecessor_drain_deadline = drain_until,
           revocation_requested_at = COALESCE(revocation_requested_at, clock_timestamp())
     WHERE id = existing_binding.id;
    SELECT COALESCE(MAX(pb.credential_generation), 0) + 1
      INTO next_generation
      FROM principal_bindings AS pb
     WHERE pb.owner_kind = 'interactive'
       AND pb.deployment_token = requested_deployment_token
       AND pb.issuing_machine_id = requested_machine_id
       AND pb.project_id = requested_project_id;
    token_slug := regexp_replace(requested_deployment_token, '[^a-zA-Z0-9]', '', 'g');
    derived_role_name := (
        'gobby_ix_'
        || substr(token_slug, 1, 8)
        || '_'
        || substr(replace(requested_machine_id::TEXT, '-', ''), 1, 8)
        || '_'
        || substr(replace(requested_project_id::TEXT, '-', ''), 1, 8)
        || '_'
        || next_generation::TEXT
    )::NAME;
    EXECUTE format(
        'CREATE ROLE %I LOGIN PASSWORD %L VALID UNTIL %L INHERIT '
        'NOSUPERUSER NOCREATEROLE NOCREATEDB NOREPLICATION NOBYPASSRLS',
        derived_role_name,
        requested_password,
        requested_expires_at
    );
    EXECUTE format(
        'GRANT %I TO %I WITH ADMIN FALSE, INHERIT TRUE, SET FALSE',
        'gobby_gcode_capability',
        derived_role_name
    );
    INSERT INTO principal_bindings (
        role_name,
        owner_kind,
        managed_execution_id,
        session_id,
        project_id,
        issuing_machine_id,
        deployment_token,
        expires_at,
        credential_generation
    ) VALUES (
        derived_role_name,
        'interactive',
        gen_random_uuid(),
        requested_session_id,
        requested_project_id,
        requested_machine_id,
        requested_deployment_token,
        requested_expires_at,
        next_generation
    ) RETURNING id INTO binding_id;
    INSERT INTO principal_audit_events (
        binding_id,
        event_type,
        managed_execution_id,
        role_name,
        credential_generation,
        project_id
    ) VALUES (
        binding_id,
        'rotate',
        (SELECT pb.managed_execution_id FROM principal_bindings AS pb WHERE pb.id = binding_id),
        derived_role_name,
        next_generation,
        requested_project_id
    );
    RETURN QUERY SELECT derived_role_name, next_generation,
        (SELECT pb.managed_execution_id FROM principal_bindings AS pb WHERE pb.id = binding_id);
END
$function$;

CREATE OR REPLACE FUNCTION gobby_agent_auth.replace_interactive_credential_material(
    requested_deployment_token TEXT,
    requested_machine_id UUID,
    requested_project_id UUID,
    requested_generation INTEGER,
    requested_ciphertext TEXT,
    requested_aad_identity TEXT
)
RETURNS BOOLEAN
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = gobby_agent_auth, pg_temp
AS $function$
BEGIN
    IF requested_ciphertext IS NULL OR requested_ciphertext = '' THEN
        RAISE EXCEPTION 'interactive credential material must be ciphertext'
            USING ERRCODE = '22023';
    END IF;
    IF requested_aad_identity IS NULL OR requested_aad_identity = '' THEN
        RAISE EXCEPTION 'interactive credential material requires AAD identity'
            USING ERRCODE = '22023';
    END IF;
    DELETE FROM interactive_credential_material
     WHERE deployment_token = requested_deployment_token
       AND machine_id = requested_machine_id
       AND project_id = requested_project_id
       AND credential_generation <> requested_generation;
    INSERT INTO interactive_credential_material (
        deployment_token,
        machine_id,
        project_id,
        credential_generation,
        ciphertext,
        aad_identity
    ) VALUES (
        requested_deployment_token,
        requested_machine_id,
        requested_project_id,
        requested_generation,
        requested_ciphertext,
        requested_aad_identity
    )
    ON CONFLICT (deployment_token, machine_id, project_id, credential_generation)
    DO UPDATE SET
        ciphertext = EXCLUDED.ciphertext,
        aad_identity = EXCLUDED.aad_identity,
        created_at = NOW();
END
$function$;

